def fetch(url, *, timeout):
    return f"{url} {timeout}"

print(fetch("/users", 5))

def report(env, build, *, verbose):
    print(env, build, verbose)

args = ["stage", 42]
opts = {"verbose": True}
report(*args, **opts)

def ping(host, port=80):
    return f"{host}:{port}"

cfg = {"host": "db", "port": 5432}
print(ping(cfg))

def log(msg, seen=[]):
    seen.append(msg)
    return len(seen)

print(log("a"), log("b"), log("c", []))

def setup(**options, mode):
    return mode

print(setup(mode="fast"))

def join(a, b, sep="-"):
    return f"{a}{sep}{b}"

def loud(*args, **kwargs):
    return join(*args, **kwargs).upper()

print(loud("q", "a", sep="+"))

def move(src, dst):
    return src + dst

print(move("a", src="b"))
